package io.github.astelev.around_planet.space;
import io.github.astelev.around_planet.PlanetConfig;
import net.minecraft.server.MinecraftServer;
import java.util.*;
/** Command-level coast jump: no world gameTime changes, loading tickets or ship recreation. */
public final class SpaceTimeWarp {
    public record Result(long ticks,String limit,int objects){}
    public static Result advance(MinecraftServer server,long requested){if(requested<=0)throw new IllegalArgumentException("Positive warp required");var level=server.overworld();long now=level.getGameTime();Math.addExact(now,requested);Math.addExact(level.getDayTime(),requested);var data=SpaceOrbitData.get(server);long actual=requested;String reason="";var warnings=net.neoforged.fml.ModList.get().isLoaded("sable")?io.github.astelev.around_planet.compat.SpaceWarpRuntime.warnings(level):Map.<UUID,Long>of();double top=PlanetConfig.SPEC.isLoaded()?Math.max(PlanetConfig.ATMOSPHERE_TOP.get(),Math.min(PlanetConfig.SPACE_ENTRY.get()-32,PlanetConfig.ATMOSPHERE_BOTTOM.get())+512):4000;
        for(var id:data.ids()){var path=data.get(id).orElseThrow();for(var node:data.maneuvers(id))if(node.tick()>=now){long limit=Math.max(0,node.tick()-now-Math.max(20,node.warningTicks(warnings.getOrDefault(id,20L))));if(limit<actual){actual=limit;reason="around_planet.warp.maneuver";}}var nav=data.navigation(id);if(nav.isPresent()&&data.reentry(id).isEmpty()){for(var leg:PatchedConics.trace(path,now,now+actual,data.system()).legs()){boolean moon=CelestialSystem.MOON.equals(leg.path().primary());if(moon&&(!net.neoforged.fml.ModList.get().isLoaded("dimensional_sable")||data.system()==null))continue;double shell=moon?data.system().moonRadius()+(PlanetConfig.SPEC.isLoaded()?PlanetConfig.MOON_LANDING.get():800):nav.get().planet().radius()+top;long span=leg.until()-leg.from(),limit=OrbitWarp.atmosphere(leg.path(),leg.from(),span,shell);if(limit<span){actual=Math.min(actual,leg.from()-now+limit);reason=moon?"around_planet.warp.surface":"around_planet.warp.atmosphere";}}}}
        // A selected rendezvous target must not pass through the capture region during the jump.
        for(var id:data.ids()){var target=data.target(id);var nav=data.navigation(id);if(target.isEmpty()||CelestialSystem.body(target.get())||nav.isEmpty()||data.reentry(id).isPresent()||data.reentry(target.get()).isPresent())continue;double distance=PlanetConfig.SPEC.isLoaded()?PlanetConfig.RENDEZVOUS_DISTANCE.get():96;if(distance<=0||!data.get(id).orElseThrow().primary().equals(data.get(target.get()).orElseThrow().primary()))continue;long limit=OrbitWarp.proximity(data.get(id).orElseThrow(),data.get(target.get()).orElseThrow(),now,actual,distance,nav.get().planet().radius()+top);if(limit<actual){actual=limit;reason="around_planet.warp.rendezvous";}}
        if(actual==0)return new Result(0,reason,data.ids().size());data.warp(now,actual);level.setDayTime(Math.addExact(level.getDayTime(),actual));if(net.neoforged.fml.ModList.get().isLoaded("sable"))io.github.astelev.around_planet.compat.SpaceWarpRuntime.refresh(level);else data.followContacts(PlanetDaylight.spin(level),now);
        for(var dimension:server.getAllLevels())for(var player:dimension.players())player.connection.send(new net.minecraft.network.protocol.game.ClientboundSetTimePacket(dimension.getGameTime(),dimension.getDayTime(),dimension.getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_DAYLIGHT)));
        io.github.astelev.around_planet.AroundPlanet.LOGGER.info("SPACE_TIME_WARP requestedTicks={} advancedTicks={} objects={} limit={}",requested,actual,data.ids().size(),reason);return new Result(actual,reason,data.ids().size());
    }
    private SpaceTimeWarp(){}
}
